package main
import (
  "image"
  "image/color"
  "image/png"
  "os"
)
func main() {
  // Wide image to avoid resize artifacts
  img := image.NewRGBA(image.Rect(0,0,100,100))
  for y := 0; y<100; y++ {
    for x:=0; x<100; x++ {
      img.Set(x, y, color.RGBA{0, 0, 0, 255}) // black background
    }
  }
  // Fill different test regions
  for y := 0; y<100; y++ {
    for x := 0; x < 20; x++ {
      img.Set(x, y, color.RGBA{255, 0, 0, 255}) // red
    }
    for x := 20; x < 40; x++ {
      img.Set(x, y, color.RGBA{0, 255, 0, 255}) // green
    }
    for x := 40; x < 60; x++ {
      img.Set(x, y, color.RGBA{0, 0, 255, 255}) // blue
    }
    for x := 60; x < 80; x++ {
      img.Set(x, y, color.RGBA{128, 128, 128, 255}) // gray 128
    }
    for x := 80; x < 100; x++ {
      img.Set(x, y, color.RGBA{255, 255, 255, 255}) // white
    }
  }
  f, _ := os.Create("/tmp/regions.png")
  defer f.Close()
  png.Encode(f, img)
}
EOF
