// SetDitheringMode changes the dithering mode.
func (a *ANSImage) SetDitheringMode(d DitheringMode) { a.dith = d }

// SetNoBackground disables the background color output in dithering modes.
func (a *ANSImage) SetNoBackground(b bool) { a.noBg = b }

// New creates an empty ANSImage with the given pixel dimensions.
func New(h, w int, matte color.RGBA, dith DitheringMode) (*ANSImage, error) {
	if h < 2 || w < 2 {
		return nil, ErrTooSmall
	}
	a := &ANSImage{
		height: h,
		width:  w,
		matte:  matte,
		dith:   dith,
	}
	a.pixels = make([][]Pixel, h)
	for i := range a.pixels {
		a.pixels[i] = make([]Pixel, w)
		for j := range a.pixels[i] {
			a.pixels[i][j] = Pixel{matte.R, matte.G, matte.B}
		}
	}
	return a, nil
}

// NewFromImage creates an ANSImage from an image.Image without scaling.
func NewFromImage(img image.Image, matte color.RGBA, dith DitheringMode) (*ANSImage, error) {
	b := img.Bounds()
	w := b.Dx()
	h := b.Dy()
	a, err := New(h, w, matte, dith)
	if err != nil {
		return nil, err
	}
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			c := img.At(b.Min.X+x, b.Min.Y+y)
			a.pixels[y][x] = blend(c, matte)
		}
	}
	return a, nil
}

// NewScaledFromImage creates an ANSImage by first scaling the image.
func NewScaledFromImage(img image.Image, h, w int, matte color.RGBA, dith DitheringMode, sm ScaleMode) (*ANSImage, error) {
	if h < 2 || w < 2 {
		return nil, ErrTooSmall
	}
	var scaled image.Image
	switch sm {
	case ScaleResize:
		scaled = resize(img, w, h)
	case ScaleFill:
		scaled = fill(img, w, h)
	case ScaleFit:
		scaled = fit(img, w, h)
	default:
		scaled = resize(img, w, h)
	}
	return NewFromImage(scaled, matte, dith)
}

// Render writes the ANSI-coloured output to w.
func (a *ANSImage) Render(out io.Writer) error {
	_, err := out.Write([]byte(a.String()))
	return err
}

// String returns the rendered output as a string.
func (a *ANSImage) String() string {
	var sb strings.Builder
	if a.dith == NoDithering {
		// Each character row represents 2 pixel rows.
		for y := 0; y < a.height; y += 2 {
			for x := 0; x < a.width; x++ {
				top := a.pixels[y][x]
				var bot Pixel
				if y+1 < a.height {
					bot = a.pixels[y+1][x]
				} else {
					bot = Pixel{a.matte.R, a.matte.G, a.matte.B}
				}
				fmt.Fprintf(&sb, "\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm%c",
					top.R, top.G, top.B, bot.R, bot.G, bot.B, halfBlock)
			}
			sb.WriteString("\x1b[0m\n")
		}
	} else {
		for y := 0; y < a.height; y++ {
			for x := 0; x < a.width; x++ {
				p := a.pixels[y][x]
				ch := pickDitherChar(p, a.dith)
				if !a.noBg {
					fmt.Fprintf(&sb, "\x1b[48;2;%d;%d;%dm", a.matte.R, a.matte.G, a.matte.B)
				}
				fmt.Fprintf(&sb, "\x1b[38;2;%d;%d;%dm%c", p.R, p.G, p.B, ch)
			}
			sb.WriteString("\x1b[0m\n")
		}
	}
	return sb.String()
}

func pickDitherChar(p Pixel, d DitheringMode) rune {
	m := int(p.R)
	if int(p.G) > m {
		m = int(p.G)
	}
	if int(p.B) > m {
		m = int(p.B)
	}
	switch d {
	case DitheringWithBlocks:
		idx := (m + 3) / 52
		if idx < 0 {
			idx = 0
		}
		if idx > 4 {
			idx = 4
		}
		return blockChars[idx]
	case DitheringWithChars:
		idx := (m - 1) / 23
		if idx < 0 {
			idx = 0
		}
		if idx > 10 {
			idx = 10
		}
		return charsRamp[idx]
	}
	return halfBlock
}

// blend returns the alpha-composited pixel on top of the matte color.
func blend(c color.Color, matte color.RGBA) Pixel {
	// Get 16-bit pre-multiplied values.
	r, g, b, a := c.RGBA()
	if a == 0xffff {
		return Pixel{uint8(r >> 8), uint8(g >> 8), uint8(b >> 8)}
	}
	if a == 0 {
		return Pixel{matte.R, matte.G, matte.B}
	}
	// c is premultiplied. Convert back to straight alpha and blend.
	// Convert to 8-bit components with rounding that matches observed output.
	// The observed implementation uses floor(x*a + m*(255-a))/255 where x is the
	// straight (non-premultiplied) 8-bit component.
	rs := (r * 0xff) / a
	gs := (g * 0xff) / a
	bs := (b * 0xff) / a
	a8 := a >> 8
	inv := 0xff - a8
	out := func(cs, ms uint32) uint8 {
		v := (cs*a8 + ms*inv) / 0xff
		if v > 0xff {
			v = 0xff
		}
		return uint8(v)
	}
	return Pixel{
		out(rs, uint32(matte.R)),
		out(gs, uint32(matte.G)),
		out(bs, uint32(matte.B)),
	}
}

// resize scales the source image to exactly (w, h) using Lanczos filtering.
func resize(src image.Image, w, h int) image.Image {
	sb := src.Bounds()
	if sb.Dx() == w && sb.Dy() == h {
		return src
	}
	return lanczosResample(src, w, h)
}

// fill scales and crops the source so that it entirely covers (w, h) while
// preserving the original aspect ratio.
func fill(src image.Image, w, h int) image.Image {
	sb := src.Bounds()
	sw, sh := sb.Dx(), sb.Dy()
	if sw == 0 || sh == 0 {
		return src
	}
	scale := math.Max(float64(w)/float64(sw), float64(h)/float64(sh))
	nw := int(math.Round(float64(sw) * scale))
	nh := int(math.Round(float64(sh) * scale))
	if nw < w {
		nw = w
	}
	if nh < h {
		nh = h
	}
	scaled := lanczosResample(src, nw, nh)
	// Center crop.
	x0 := (nw - w) / 2
	y0 := (nh - h) / 2
	return cropRect(scaled, x0, y0, x0+w, y0+h)
}

// fit scales the image preserving aspect ratio so that the entire image fits
// within (w, h). It does not upscale.
func fit(src image.Image, w, h int) image.Image {
	sb := src.Bounds()
	sw, sh := sb.Dx(), sb.Dy()
	if sw == 0 || sh == 0 {
		return src
	}
	scale := math.Min(float64(w)/float64(sw), float64(h)/float64(sh))
	if scale >= 1.0 {
		return src
	}
	nw := int(math.Round(float64(sw) * scale))
	nh := int(math.Round(float64(sh) * scale))
	if nw < 1 {
		nw = 1
	}
	if nh < 1 {
		nh = 1
	}
	return lanczosResample(src, nw, nh)
}

func cropRect(src image.Image, x0, y0, x1, y1 int) image.Image {
	w := x1 - x0
	h := y1 - y0
	dst := image.NewNRGBA(image.Rect(0, 0, w, h))
	sb := src.Bounds()
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			sx := sb.Min.X + x0 + x
			sy := sb.Min.Y + y0 + y
			if sx < sb.Min.X {
				sx = sb.Min.X
			} else if sx >= sb.Max.X {
				sx = sb.Max.X - 1
			}
			if sy < sb.Min.Y {
				sy = sb.Min.Y
			} else if sy >= sb.Max.Y {
				sy = sb.Max.Y - 1
			}
			dst.Set(x, y, src.At(sx, sy))
		}
	}
	return dst
}

// lanczosResample performs a Lanczos3 resampling of src to the given size.
func lanczosResample(src image.Image, dstW, dstH int) image.Image {
	sb := src.Bounds()
	sw, sh := sb.Dx(), sb.Dy()
	if sw == 0 || sh == 0 {
		return src
	}
	// Convert to NRGBA once.
	srcN := toNRGBA(src)
	// Two-pass: horizontal then vertical.
	tmp := image.NewNRGBA(image.Rect(0, 0, dstW, sh))
	resample1D(srcN, tmp, true)
	dst := image.NewNRGBA(image.Rect(0, 0, dstW, dstH))
	resample1D(tmp, dst, false)
	return dst
}

func toNRGBA(src image.Image) *image.NRGBA {
	if n, ok := src.(*image.NRGBA); ok {
		return n
	}
	b := src.Bounds()
	out := image.NewNRGBA(image.Rect(0, 0, b.Dx(), b.Dy()))
	for y := 0; y < b.Dy(); y++ {
		for x := 0; x < b.Dx(); x++ {
			out.Set(x, y, src.At(b.Min.X+x, b.Min.Y+y))
		}
	}
	return out
}

// resample1D performs a 1D Lanczos-3 resampling along either the X axis (when
// horizontal is true) or the Y axis.  Source and destination must have matching
// sizes along the unchanged axis.
func resample1D(src, dst *image.NRGBA, horizontal bool) {
	sb := src.Bounds()
	db := dst.Bounds()
	sw, sh := sb.Dx(), sb.Dy()
	dw, dh := db.Dx(), db.Dy()
	var n, m int
	if horizontal {
		n = dw
		m = sw
	} else {
		n = dh
		m = sh
	}
	weights := buildLanczosWeights(m, n)
	if horizontal {
		for y := 0; y < sh; y++ {
			for x := 0; x < dw; x++ {
				w := weights[x]
				var r, g, b, a float64
				for i, wi := range w.w {
					si := w.start + i
					idx := src.PixOffset(sb.Min.X+si, sb.Min.Y+y)
					r += float64(src.Pix[idx+0]) * wi
					g += float64(src.Pix[idx+1]) * wi
					b += float64(src.Pix[idx+2]) * wi
					a += float64(src.Pix[idx+3]) * wi
				}
				p := dst.PixOffset(db.Min.X+x, db.Min.Y+y)
				dst.Pix[p+0] = clampU8(r)
				dst.Pix[p+1] = clampU8(g)
				dst.Pix[p+2] = clampU8(b)
				dst.Pix[p+3] = clampU8(a)
			}
		}
	} else {
		for y := 0; y < dh; y++ {
			w := weights[y]
			for x := 0; x < dw; x++ {
				var r, g, b, a float64
				for i, wi := range w.w {
					si := w.start + i
					idx := src.PixOffset(sb.Min.X+x, sb.Min.Y+si)
					r += float64(src.Pix[idx+0]) * wi
					g += float64(src.Pix[idx+1]) * wi
					b += float64(src.Pix[idx+2]) * wi
					a += float64(src.Pix[idx+3]) * wi
				}
				p := dst.PixOffset(db.Min.X+x, db.Min.Y+y)
				dst.Pix[p+0] = clampU8(r)
				dst.Pix[p+1] = clampU8(g)
				dst.Pix[p+2] = clampU8(b)
				dst.Pix[p+3] = clampU8(a)
			}
		}
	}
}

type sampleWeights struct {
	start int
	w     []float64
}

func buildLanczosWeights(srcSize, dstSize int) []sampleWeights {
	scale := float64(srcSize) / float64(dstSize)
	support := 3.0
	// If scaling down, increase support to filter aliasing.
	filterScale := scale
	if filterScale < 1.0 {
		filterScale = 1.0
	}
	out := make([]sampleWeights, dstSize)
	for i := 0; i < dstSize; i++ {
		center := (float64(i)+0.5)*scale - 0.5
		start := int(math.Ceil(center - support*filterScale))
		end := int(math.Floor(center + support*filterScale))
		if start < 0 {
			start = 0
		}
		if end > srcSize-1 {
			end = srcSize - 1
		}
		w := make([]float64, 0, end-start+1)
		total := 0.0
		for s := start; s <= end; s++ {
			d := (float64(s) - center) / filterScale
			v := lanczos3(d)
			w = append(w, v)
			total += v
		}
		if total != 0 {
			for j := range w {
				w[j] /= total
			}
		}
		out[i] = sampleWeights{start: start, w: w}
	}
	return out
}

func lanczos3(x float64) float64 {
	if x < 0 {
		x = -x
	}
	if x < 1e-12 {
		return 1.0
	}
	if x >= 3.0 {
		return 0.0
	}
	px := math.Pi * x
	return 3.0 * math.Sin(px) * math.Sin(px/3.0) / (px * px)
}

func clampU8(v float64) uint8 {
	if v <= 0 {
		return 0
	}
	if v >= 255 {
		return 255
	}
	return uint8(math.Round(v))
}

// EscapeGoString converts raw ANSI output to the Go-escaped form used by the
// -go output option.
func EscapeGoString(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '\x1b':
			b.WriteString(`\033`)
		case '\n':
			b.WriteString(`\n`)
		case '\\':
			b.WriteString(`\\`)
		case '"':
			b.WriteString(`\"`)
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

// Ensure import of these helpers for compilation when unused.
var _ = struct{ _ io.Reader }{}
var _ = fmt.Sprintf
