func pickDitherChar(p Pixel, d DitheringMode) rune {
	m := int(p.R)
	if int(p.G) > m {
		m = int(p.G)
	}
	if int(p.B) > m {
		m = int(p.B)
	}
	switch d {
	case DitheringWithBlocks:
		idx := (m + 3) / 52
		if idx < 0 {
			idx = 0
		}
		if idx > 4 {
			idx = 4
		}
		return blockChars[idx]
	case DitheringWithChars:
		idx := (m - 1) / 23
		if idx < 0 {
			idx = 0
		}
		if idx > 10 {
			idx = 10
		}
		return charsRamp[idx]
	}
	return halfBlock
