// horizontal is true) or the Y axis.  Source and destination must have matching
// sizes along the unchanged axis.
func resample1D(src, dst *image.NRGBA, horizontal bool) {
	sb := src.Bounds()
	db := dst.Bounds()
	sw, sh := sb.Dx(), sb.Dy()
	dw, dh := db.Dx(), db.Dy()
	var n, m int
	if horizontal {
		n = dw
		m = sw
	} else {
		n = dh
		m = sh
	}
	weights := buildLanczosWeights(m, n)
	if horizontal {
		for y := 0; y < sh; y++ {
			for x := 0; x < dw; x++ {
				w := weights[x]
				var r, g, b, a float64
				for i, wi := range w.w {
					si := w.start + i
					idx := src.PixOffset(sb.Min.X+si, sb.Min.Y+y)
					r += float64(src.Pix[idx+0]) * wi
					g += float64(src.Pix[idx+1]) * wi
					b += float64(src.Pix[idx+2]) * wi
					a += float64(src.Pix[idx+3]) * wi
				}
				p := dst.PixOffset(db.Min.X+x, db.Min.Y+y)
				dst.Pix[p+0] = clampU8(r)
				dst.Pix[p+1] = clampU8(g)
				dst.Pix[p+2] = clampU8(b)
				dst.Pix[p+3] = clampU8(a)
			}
		}
	} else {
		for y := 0; y < dh; y++ {
			w := weights[y]
			for x := 0; x < dw; x++ {
				var r, g, b, a float64
				for i, wi := range w.w {
					si := w.start + i
					idx := src.PixOffset(sb.Min.X+x, sb.Min.Y+si)
					r += float64(src.Pix[idx+0]) * wi
					g += float64(src.Pix[idx+1]) * wi
					b += float64(src.Pix[idx+2]) * wi
					a += float64(src.Pix[idx+3]) * wi
				}
				p := dst.PixOffset(db.Min.X+x, db.Min.Y+y)
				dst.Pix[p+0] = clampU8(r)
				dst.Pix[p+1] = clampU8(g)
				dst.Pix[p+2] = clampU8(b)
				dst.Pix[p+3] = clampU8(a)
			}
		}
	}
}

type sampleWeights struct {
	start int
	w     []float64
}

func buildLanczosWeights(srcSize, dstSize int) []sampleWeights {
	scale := float64(srcSize) / float64(dstSize)
	support := 3.0
	// If scaling down, increase support to filter aliasing.
	filterScale := scale
	if filterScale < 1.0 {
		filterScale = 1.0
	}
	out := make([]sampleWeights, dstSize)
	for i := 0; i < dstSize; i++ {
		center := (float64(i)+0.5)*scale - 0.5
		start := int(math.Ceil(center - support*filterScale))
		end := int(math.Floor(center + support*filterScale))
		if start < 0 {
			start = 0
		}
		if end > srcSize-1 {
			end = srcSize - 1
		}
		w := make([]float64, 0, end-start+1)
		total := 0.0
		for s := start; s <= end; s++ {
			d := (float64(s) - center) / filterScale
			v := lanczos3(d)
			w = append(w, v)
			total += v
		}
		if total != 0 {
			for j := range w {
				w[j] /= total
			}
		}
		out[i] = sampleWeights{start: start, w: w}
	}
	return out
}

func lanczos3(x float64) float64 {
	if x < 0 {
		x = -x
	}
	if x < 1e-12 {
		return 1.0
	}
	if x >= 3.0 {
		return 0.0
	}
	px := math.Pi * x
	return 3.0 * math.Sin(px) * math.Sin(px/3.0) / (px * px)
}

func clampU8(v float64) uint8 {
	if v <= 0 {
		return 0
	}
	if v >= 255 {
		return 255
	}
	return uint8(math.Round(v))
}

// EscapeGoString converts raw ANSI output to the Go-escaped form used by the
// -go output option.
func EscapeGoString(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '\x1b':
			b.WriteString(`\033`)
		case '\n':
			b.WriteString(`\n`)
		case '\\':
			b.WriteString(`\\`)
		case '"':
			b.WriteString(`\"`)
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

