// Pixterm is a terminal image viewer that renders images using ANSI true-color.
package main

import (
	"bytes"
	"flag"
	"fmt"
	"image"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"image/color"
	"io"
	"log"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"pixterm/internal/ansimage"
)

const (
	pixVersion = "1.3.2"
	errPrefix  = "[PIXTERM ERROR] "
)

const banner = `   ___  _____  ____
  / _ \/  _/ |/_/ /____ ______ _      Made with love by Eliuk Blau
 / ___// /_>  </ __/ -_) __/  ' \ https://github.com/eliukblau/pixterm
/_/  /___/_/|_|\__/\__/_/ /_/_/_/                1.3.2
`

const credits = `CONTRIBUTORS:

  > @disq - https://github.com/disq
      + Original code for image transparency support.

  > @timob - https://github.com/timob
      + Fix for ANSIpixel type: use 8bit color component for output.

  > @HongjiangHuang - https://github.com/HongjiangHuang
      + Original code for image download support.

  > @brutestack - https://github.com/brutestack
      + Color support for Windows (Command Prompt & PowerShell).
      + Original code for disable background color in dithering mode.
      + Original code for output Go code to 'fmt.Print()' the image.

  > @diamondburned - https://github.com/diamondburned
      + NewFromImage() & NewScaledFromImage() for ANSImage API.

  > @MichaelMure - https://github.com/MichaelMure
      + More conventional 'go.mod' file at repository.

  > @Calinou - https://github.com/Calinou
      + Use HTTPS URLs everywhere.
      + Other awesome contributions.

  > @danirod - https://github.com/danirod
  > @Xpktro - https://github.com/Xpktro
      + Moral support.

`

func main() {
	log.SetFlags(log.LstdFlags)
	log.SetPrefix(errPrefix)

	progName := filepath.Base(os.Args[0])

	fs := flag.NewFlagSet(progName, flag.ContinueOnError)
	fs.SetOutput(io.Discard)

	credFlag := fs.Bool("credits", false, "show some love to contributors <3")
	dMode := fs.Int("d", 0, "")
	goOut := fs.Bool("go", false, "output Go code to 'fmt.Print()' the image")
	mColor := fs.String("m", "000000", "")
	noBg := fs.Bool("nobg", false, "")
	sMode := fs.Int("s", 0, "")
	tc := fs.Int("tc", 0, "")
	tr := fs.Int("tr", 0, "")
	versionFlag := fs.Bool("version", false, "show PIXterm version")
	helpFlag := fs.Bool("help", false, "prints this message :D LOL")

	args := os.Args[1:]
	err := fs.Parse(args)

	// Always print the banner first on stdout.
	fmt.Println(banner)

	if err != nil {
		// -help explicitly asked, or an unknown/mal-formed flag.
		if err == flag.ErrHelp {
			printUsage(progName)
			os.Exit(0)
		}
		printUsage(progName)
		os.Exit(2)
	}

	if *helpFlag {
		printUsage(progName)
		os.Exit(0)
	}

	if *versionFlag {
		fmt.Println(pixVersion)
		os.Exit(0)
	}

	if *credFlag {
		fmt.Print(credits)
		os.Exit(0)
	}

	remaining := fs.Args()
	if len(remaining) == 0 {
		printUsage(progName)
		os.Exit(2)
	}

	if *dMode < 0 || *dMode > 2 {
		printUsage(progName)
		os.Exit(2)
	}
	if *sMode < 0 || *sMode > 2 {
		printUsage(progName)
		os.Exit(2)
	}
	if (*tc != 0 && *tc < 2) || (*tr != 0 && *tr < 2) {
		printUsage(progName)
		os.Exit(2)
	}

	matte, ok := parseHexColor(*mColor)
	if !ok {
		log.Fatalf("matte color : %s is not a hex-color", *mColor)
	}

	source := remaining[0]

	img, err := loadImage(source)
	if err != nil {
		log.Fatal(err)
	}

	tCols, tRows := *tc, *tr
	if tCols == 0 {
		tCols = terminalCols()
	}
	if tRows == 0 {
		tRows = terminalRows()
	}

	if tCols < 2 || tRows < 2 {
		printUsage(progName)
		os.Exit(2)
	}

	dith := ansimage.DitheringMode(*dMode)
	scale := ansimage.ScaleMode(*sMode)

	var targetH, targetW int
	if dith == ansimage.NoDithering {
		targetH = 2 * tRows
		targetW = tCols
	} else {
		targetH = tRows
		targetW = tCols
	}

	a, err := ansimage.NewScaledFromImage(img, targetH, targetW, matte, dith, scale)
	if err != nil {
		log.Fatal(err)
	}
	if *noBg {
		a.SetNoBackground(true)
	}

	out := a.String()
	if *goOut {
		emitGoCode(out)
	} else {
		fmt.Print(out)
	}
}

func emitGoCode(raw string) {
	var sb strings.Builder
	// Each line of raw ends with "\x1b[0m\n". Wrap it with fmt.Print("...\n").
	lines := strings.SplitAfter(raw, "\n")
	for _, line := range lines {
		if line == "" {
			continue
		}
		sb.WriteString(`fmt.Print("`)
		sb.WriteString(ansimage.EscapeGoString(line))
		sb.WriteString("\")\n")
	}
	fmt.Print(sb.String())
}

func loadImage(src string) (image.Image, error) {
	lower := strings.ToLower(src)
	if strings.HasPrefix(lower, "http://") || strings.HasPrefix(lower, "https://") {
		u, err := url.Parse(src)
		if err != nil {
			return nil, err
		}
		resp, err := http.Get(u.String())
		if err != nil {
			return nil, err
		}
		defer resp.Body.Close()
		buf, err := io.ReadAll(resp.Body)
		if err != nil {
			return nil, err
		}
		img, _, err := image.Decode(bytes.NewReader(buf))
		return img, err
	}
	f, err := os.Open(src)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	img, _, err := image.Decode(f)
	return img, err
}

