		r = hexByte(string(s[0]) + string(s[0]))
		g = hexByte(string(s[1]) + string(s[1]))
		b = hexByte(string(s[2]) + string(s[2]))
	case n == 5:
		r = hexByte(s[0:2])
		g = hexByte(s[2:4])
		b = hexByte(string(s[4]))
	case n >= 6:
		r = hexByte(s[0:2])
