		b = hexByte(s[4:6])
	default:
		return color.RGBA{}, false
	}
	return color.RGBA{r, g, b, 0xff}, true
}

func isHex(r rune) bool {
	return (r >= '0' && r <= '9') || (r >= 'a' && r <= 'f') || (r >= 'A' && r <= 'F')
}

