package main

import (
	"os"
	"syscall"
	"unsafe"
)

// ioctl constants (for Linux).
const tiocgwinsz = 0x5413

type winSize struct {
	rows    uint16
	cols    uint16
	xpixels uint16
	ypixels uint16
}

func termSize(f *os.File) (cols, rows int, ok bool) {
	var ws winSize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), tiocgwinsz, uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 0, 0, false
	}
	return int(ws.cols), int(ws.rows), true
}
