func fit(src image.Image, w, h int) image.Image {
	sb := src.Bounds()
	sw, sh := sb.Dx(), sb.Dy()
	if sw == 0 || sh == 0 {
		return src
	}
	scale := math.Min(float64(w)/float64(sw), float64(h)/float64(sh))
	if scale >= 1.0 {
		return src
	}
	nw := int(math.Round(float64(sw) * scale))
	nh := int(math.Round(float64(sh) * scale))
	if nw < 1 {
		nw = 1
	}
	if nh < 1 {
		nh = 1
	}
	return lanczosResample(src, nw, nh)
}'''

new_fit = '''// fit scales the image preserving aspect ratio (measured in characters) so
// that it fits within a (w x h) pixel canvas. The algorithm matches the
// pixterm behaviour: the top two pixel rows of the resulting image are
// cropped so the output height is always a multiple of two pixels.
func fit(src image.Image, w, h int) image.Image {
	sb := src.Bounds()
	W := sb.Dx()
	H := sb.Dy()
	if W < 2 || H < 2 {
		return src
	}
	// In character units. Each character shows two vertical pixels; the
	// original pixterm implementation cuts away a one-character band from
	// the top of the image.
	HChars := (H - 2) / 2
	if HChars < 1 {
		HChars = 1
	}
	WChars := W

	trChars := h / 2
	if trChars < 1 {
		trChars = 1
	}
	tcChars := w

	newH := trChars
	if newH > HChars {
		newH = HChars
	}
	newW := tcChars
	if newW > WChars {
		newW = WChars
	}
	// Aspect-preserve: shrink the axis whose ratio is too large.
	if newW*HChars > newH*WChars {
		newW = newH * WChars / HChars
	} else if newW*HChars < newH*WChars {
		newH = newW * HChars / WChars
	}
	if newW < 1 {
		newW = 1
	}
	if newH < 1 {
		newH = 1
	}
	scaledH := 2*newH + 2
	scaledW := newW
	var scaled image.Image
	if scaledW == W && scaledH == H {
		scaled = src
	} else {
		scaled = lanczosResample(src, scaledW, scaledH)
	}
	// Crop the top two pixel rows.
	return cropRect(scaled, 0, 2, scaledW, scaledH)
}'''

