	if h < 2 || w < 2 {
		return nil, ErrTooSmall
	}
	targetW := w
	targetH := h
	// In dithering modes, each character holds a single pixel vertically
	// (instead of two), so we ultimately need half the pixel height.
	if dith != NoDithering {
