	case ScaleResize:
		scaled = resize(img, targetW, targetH)
	case ScaleFill:
		scaled = fill(img, targetW, targetH)
	case ScaleFit:
		scaled = fit(img, targetW, targetH)
		// For dithering modes, halve vertically to produce one pixel per char.
		if dith != NoDithering {
			sb := scaled.Bounds()
			if sb.Dx() >= 2 && sb.Dy() >= 2 {
