	r, g, b, a := c.RGBA()
	if a == 0xffff {
		return Pixel{uint8(r >> 8), uint8(g >> 8), uint8(b >> 8)}
	}
	mR := uint32(matte.R) * 0x101
	mG := uint32(matte.G) * 0x101
	mB := uint32(matte.B) * 0x101
	if a == 0 {
		return Pixel{uint8(mR >> 8), uint8(mG >> 8), uint8(mB >> 8)}
	}
	// Composite: out_pm = src_pm + matte_pm * (0xffff - a) / 0xffff.
	inv := uint32(0xffff) - a
	out := func(cpm, mpm uint32) uint8 {
		v := cpm + (mpm*inv)/0xffff
		if v > 0xffff {
			v = 0xffff
		}
		return uint8(v >> 8)
	}
	return Pixel{
		out(r, mR),
		out(g, mG),
		out(b, mB),
	}
}'''
